import{_ as e,o as s,c as t,a2 as c}from"./chunks/framework.CHeM0PsO.js";const b=JSON.parse('{"title":"キャッシュ","description":"","frontmatter":{},"headers":[],"relativePath":"ja/advanced/caching.md","filePath":"ja/advanced/caching.md","lastUpdated":1784903584000}'),n={name:"ja/advanced/caching.md"};function i(d,a,o,p,l,r){return s(),t("div",null,[...a[0]||(a[0]=[c(`<h1 id="キャッシュ" tabindex="-1">キャッシュ <a class="header-anchor" href="#キャッシュ" aria-label="Permalink to &quot;キャッシュ&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>swag2mcp はダウンロードした spec ファイルをキャッシュするため、MCP サーバーが次回以降より速く起動します。毎回同じ spec ファイルをダウンロードする代わりに、キャッシュされたコピーを再利用します。</p><h2 id="キャッシュの仕組み" tabindex="-1">キャッシュの仕組み <a class="header-anchor" href="#キャッシュの仕組み" aria-label="Permalink to &quot;キャッシュの仕組み&quot;">​</a></h2><p>リモート URL で spec を追加すると、swag2mcp はそれをダウンロードして <code>cache/</code> ディレクトリに保存します。次回の起動時に、キャッシュされたコピーがまだ有効かどうかを確認します。有効な場合、ダウンロードはスキップされます。</p><h3 id="キャッシュされるもの" tabindex="-1">キャッシュされるもの <a class="header-anchor" href="#キャッシュされるもの" aria-label="Permalink to &quot;キャッシュされるもの&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ソース</th><th>動作</th></tr></thead><tbody><tr><td><strong>リモート URL</strong> (http/https)</td><td>常にキャッシュ。一度ダウンロードされ、キャッシュが期限切れになるまで再利用。</td></tr><tr><td><strong><code>specs/</code> 内のローカルファイル</strong></td><td><code>specs/</code> ディレクトリから直接使用。キャッシュされない — 変更は即座に反映。</td></tr><tr><td><strong><code>specs/</code> 外のローカルファイル</strong></td><td>キャッシュにコピー。ソースファイルが変更されると（更新日時）、キャッシュは無効化。</td></tr></tbody></table><h3 id="キャッシュの有効期限-ttl" tabindex="-1">キャッシュの有効期限（TTL） <a class="header-anchor" href="#キャッシュの有効期限-ttl" aria-label="Permalink to &quot;キャッシュの有効期限（TTL）&quot;">​</a></h3><p>各キャッシュファイルには <strong>1 時間から 48 時間</strong> の間でランダムな有効期限が設定されます。ランダム性により、すべてのキャッシュファイルが同時に期限切れになるのを防ぎます（ダウンロードの雪崩を防止）。</p><ul><li>TTL は MCP サーバーが起動するたびにリセットされます</li><li>キャッシュファイルが TTL 内にある場合、再利用されます</li><li>TTL が期限切れの場合、ファイルは再ダウンロードされます</li></ul><h3 id="キャッシュ構造" tabindex="-1">キャッシュ構造 <a class="header-anchor" href="#キャッシュ構造" aria-label="Permalink to &quot;キャッシュ構造&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # キャッシュされた spec ファイル</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # メタデータ（ソース、TTL、キャッシュ日時）</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>キャッシュキーは spec ファイルの URL またはパスから導出されます。各キャッシュファイルには、キャッシュ日時と有効期限を保存する <code>.meta</code> ファイルが付属します。</p><h2 id="キャッシュの管理" tabindex="-1">キャッシュの管理 <a class="header-anchor" href="#キャッシュの管理" aria-label="Permalink to &quot;キャッシュの管理&quot;">​</a></h2><h3 id="強制リフレッシュ" tabindex="-1">強制リフレッシュ <a class="header-anchor" href="#強制リフレッシュ" aria-label="Permalink to &quot;強制リフレッシュ&quot;">​</a></h3><p><code>swag2mcp update</code> を実行してキャッシュ全体をクリアし、すべての spec ファイルを再ダウンロードします：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>設定を検証し、キャッシュをクリアし、すべてを新しくダウンロードします。</p><h3 id="手動でキャッシュをクリア" tabindex="-1">手動でキャッシュをクリア <a class="header-anchor" href="#手動でキャッシュをクリア" aria-label="Permalink to &quot;手動でキャッシュをクリア&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>キャッシュされたすべての spec ファイルと保存された API レスポンスを削除します。次回 MCP サーバーを起動すると、すべての spec が再ダウンロードされます。</p><h3 id="自動クリーンアップ" tabindex="-1">自動クリーンアップ <a class="header-anchor" href="#自動クリーンアップ" aria-label="Permalink to &quot;自動クリーンアップ&quot;">​</a></h3><p>MCP サーバーが起動するとき（<code>swag2mcp mcp</code>）、48 時間以上経過した保存済み API レスポンスが自動的に削除されます。これにより <code>responses/</code> ディレクトリが無制限に増大するのを防ぎます。</p><h2 id="重要な注意点" tabindex="-1">重要な注意点 <a class="header-anchor" href="#重要な注意点" aria-label="Permalink to &quot;重要な注意点&quot;">​</a></h2><ul><li><strong><code>specs/</code> 内のローカルファイルはキャッシュされません</strong> — <code>specs/</code> ディレクトリ内の spec ファイルを直接編集した場合、キャッシュをクリアしなくても変更は即座に反映されます</li><li><strong>リモート URL は常にキャッシュされます</strong> — <code>swag2mcp update</code> または <code>swag2mcp clean</code> を実行する以外に、リモート URL のキャッシュをバイパスする方法はありません</li><li><strong>キャッシュはローカルです</strong> — ディスクに保存され、マシン間で同期されません。マシン間で spec を転送するには <code>swag2mcp export</code> と <code>swag2mcp import</code> を使用してください</li></ul>`,25)])])}const g=e(n,[["render",i]]);export{b as __pageData,g as default};
